import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {prisma} from '../src/lib/db';
// CSV seed files generated by Python seed scripts. CSV values are quoted without embedded newlines.
function parseCsv(path:string){const text=readFileSync(resolve(process.cwd(),path),'utf8');const lines=text.trim().split(/\r?\n/);const headers=parseLine(lines.shift()!);return lines.map(line=>Object.fromEntries(parseLine(line).map((v,i)=>[headers[i],v])))}
function parseLine(line:string){const out:string[]=[];let item='';let quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){item+='"';i++}else quoted=!quoted;}else if(c===','&&!quoted){out.push(item);item=''}else item+=c;}out.push(item);return out}
async function main(){const lines=parseCsv('data/verses_1000_drafts.csv');const briefs=parseCsv('data/design_briefs_1000.csv');
 for(const x of lines){await prisma.quoteDraft.upsert({where:{fingerprint:x.fingerprint},create:{fingerprint:x.fingerprint,text:x.text,language:x.language,theme:x.theme,originType:x.origin_type,editorialStatus:x.status},update:{}})}
 for(const b of briefs){await prisma.designBrief.upsert({where:{fingerprint:b.fingerprint},create:{fingerprint:b.fingerprint,quoteFingerprint:b.quote_fingerprint,quoteText:b.quote_text,theme:b.theme,garmentFamily:b.garment_family,artFamily:b.art_family,placement:b.placement,motif:b.motif,palette:b.palette,fit:b.fit,state:'DRAFT'},update:{}})}
 console.log('Imported',lines.length,'draft quotes and',briefs.length,'distinct draft design briefs');
}
main().catch(e=>{console.error(e);process.exitCode=1}).finally(async()=>prisma.$disconnect());
